<?php require dirname(__DIR__).'/app/bootstrap.php';$me=require_login();require_permission('staff.manage_roles');
$roles=['reporter','investigative_reporter','fact_checker','copy_editor','photographer','video_producer','multimedia_editor','section_editor','managing_editor','editor_in_chief','legal_reviewer','seo_audience_editor','social_media_manager','advertising_manager','finance_officer','subscriber_support','external_contributor','publisher','system_administrator'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();try{$id=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'');$reauth=query_one('SELECT password_hash FROM users WHERE id=?',[(int)$me['id']]);if(!$reauth||!password_verify((string)($_POST['current_password']??''),$reauth['password_hash']))throw new RuntimeException('Your current password is required for role changes.');$target=query_one('SELECT id,role FROM users WHERE id=?',[$id]);if(!$target||!in_array($role,$roles,true))throw new RuntimeException('Invalid user or role.');
  if(($_POST['action']??'')==='assign_role'){
   $existing=load_user_roles($id,(string)$target['role']);if(($role==='system_administrator'&&array_diff($existing,['system_administrator']))||((string)$target['role']==='system_administrator'&&$role!=='system_administrator'))throw new RuntimeException('System administration cannot be combined with editorial or commercial roles.');
   if(db_is_sqlite())db()->prepare("INSERT OR IGNORE INTO user_roles(user_id,role_key,assigned_by) VALUES (?,?,?)")->execute([$id,$role,(int)$me['id']]);else db()->prepare('INSERT IGNORE INTO user_roles(user_id,role_key,assigned_by) VALUES (?,?,?)')->execute([$id,$role,(int)$me['id']]);audit_log('assign_role','user',$id,$role);
  }elseif(($_POST['action']??'')==='remove_role'){
   if($role===$target['role'])throw new RuntimeException('Primary role cannot be removed; assign/change the primary role through a reviewed administration process.');db()->prepare('DELETE FROM user_roles WHERE user_id=? AND role_key=?')->execute([$id,$role]);audit_log('remove_role','user',$id,$role);
  }else throw new RuntimeException('Unknown role action.');db()->prepare('UPDATE users SET session_version=session_version+1 WHERE id=?')->execute([$id]);flash('Role matrix updated and sessions revoked.');header('Location: '.path('admin/roles.php'));exit;
 }catch(Throwable $e){$error=$e->getMessage();}
}
$users=query_all("SELECT u.id,u.full_name,u.email,u.role,GROUP_CONCAT(ur.role_key) roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id GROUP BY u.id,u.full_name,u.email,u.role ORDER BY u.full_name");
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Role Matrix · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1200px;margin:auto"><p><a href="<?=e(path('admin/index.php?page=users'))?>">← Staff management</a></p><div class="admin-section-title"><h1>Role & Permission Matrix<span class="brand-accent">.</span></h1></div><p>Role changes revoke existing sessions, require MFA for the administrator and require current-password reauthentication. Technical system administration cannot be combined with editorial/commercial authority.</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice"><?=e($msg)?></div><?php endif;?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>USER</th><th>ASSIGNED ROLES</th><th>ASSIGN</th><th>REMOVE SECONDARY</th></tr></thead><tbody><?php foreach($users as $u):$assigned=array_filter(explode(',',(string)$u['roles']));?><tr><td><b><?=e($u['full_name'])?></b><br><?=e($u['email'])?></td><td><?=e(implode(', ',$assigned?:[$u['role']]))?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="assign_role"><input type="hidden" name="user_id" value="<?=$u['id']?>"><select name="role"><?php foreach($roles as $r):?><option value="<?=$r?>"><?=e(str_replace('_',' ',$r))?></option><?php endforeach;?></select><input type="password" name="current_password" placeholder="Your current password" autocomplete="current-password" required><button>ASSIGN</button></form></td><td><?php foreach($assigned as $r)if($r!==$u['role']):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="remove_role"><input type="hidden" name="user_id" value="<?=$u['id']?>"><input type="hidden" name="role" value="<?=e($r)?>"><input type="password" name="current_password" placeholder="Your current password" autocomplete="current-password" required><button><?=e($r)?> ×</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
